   136	function createTaskAndNavigate(
   137	    parentReportID: string | undefined,
   138	    title: string,
   139	    description: string,
   140	    assigneeEmail: string,
   141	    assigneeAccountID = 0,
   142	    assigneeChatReport?: OnyxEntry<OnyxTypes.Report>,
   143	    policyID: string = CONST.POLICY.OWNER_EMAIL_FAKE,
