   158	    const optimisticAddCommentReport = ReportUtils.buildOptimisticTaskCommentReportAction(taskReportID, title, assigneeAccountID, `task for ${title}`, parentReportID);
   159	    optimisticTaskReport.parentReportActionID = optimisticAddCommentReport.reportAction.reportActionID;
   160	
   161	    const currentTime = DateUtils.getDBTimeWithSkew();
   162	    const lastCommentText = ReportUtils.formatReportLastMessageText(ReportActionsUtils.getReportActionText(optimisticAddCommentReport.reportAction));
   163	    const parentReport = allReports?.[`${ONYXKEYS.COLLECTION.REPORT}${parentReportID}`];
   164	    const optimisticParentReport = {
   165	        lastVisibleActionCreated: optimisticAddCommentReport.reportAction.created,
   166	        lastMessageText: lastCommentText,
   167	        lastActorAccountID: currentUserAccountID,
   168	        lastReadTime: currentTime,
   169	        hasOutstandingChildTask: assigneeAccountID === currentUserAccountID ? true : parentReport?.hasOutstandingChildTask,
   170	    };
   171	
   172	    // We're only setting onyx data for the task report here because it's possible for the parent report to not exist yet (if you're assigning a task to someone you haven't chatted with before)
   173	    // So we don't want to set the parent report data until we've successfully created that chat report
   174	    // FOR TASK REPORT
   175	    const optimisticData: OnyxUpdate[] = [
   176	        {
   177	            onyxMethod: Onyx.METHOD.SET,
   178	            key: `${ONYXKEYS.COLLECTION.REPORT}${optimisticTaskReport.reportID}`,
   179	            value: {
   180	                ...optimisticTaskReport,
   181	                pendingFields: {
   182	                    createChat: CONST.RED_BRICK_ROAD_PENDING_ACTION.ADD,
   183	                    reportName: CONST.RED_BRICK_ROAD_PENDING_ACTION.ADD,
   184	                    description: CONST.RED_BRICK_ROAD_PENDING_ACTION.ADD,
