   186	                },
   187	            },
   188	        },
   189	        {
   190	            onyxMethod: Onyx.METHOD.MERGE,
   191	            key: `${ONYXKEYS.COLLECTION.REPORT_METADATA}${optimisticTaskReport.reportID}`,
   192	            value: {
   193	                isOptimisticReport: true,
   194	            },
   195	        },
   196	        {
   197	            onyxMethod: Onyx.METHOD.SET,
   198	            key: `${ONYXKEYS.COLLECTION.REPORT_ACTIONS}${optimisticTaskReport.reportID}`,
   199	            value: {[optimisticTaskCreatedAction.reportActionID]: optimisticTaskCreatedAction as OnyxTypes.ReportAction},
   200	        },
   201	    ];
   202	
   203	    // FOR TASK REPORT
   204	    const successData: OnyxUpdate[] = [
   205	        {
   206	            onyxMethod: Onyx.METHOD.MERGE,
   207	            key: `${ONYXKEYS.COLLECTION.REPORT}${optimisticTaskReport.reportID}`,
   208	            value: {
   209	                pendingFields: {
   210	                    createChat: null,
   211	                    reportName: null,
   212	                    description: null,
   213	                    managerID: null,
   214	                },
   215	                // BE will send a different participant. We clear the optimistic one to avoid duplicated entries
   216	                participants: {[assigneeAccountID]: null},
   217	            },
   218	        },
   219	        {
   220	            onyxMethod: Onyx.METHOD.MERGE,
   221	            key: `${ONYXKEYS.COLLECTION.REPORT_METADATA}${optimisticTaskReport.reportID}`,
   222	            value: {
   223	                isOptimisticReport: false,
   224	            },
   225	        },
   226	        {
   227	            onyxMethod: Onyx.METHOD.MERGE,
   228	            key: `${ONYXKEYS.COLLECTION.REPORT_ACTIONS}${optimisticTaskReport.reportID}`,
   229	            value: {[optimisticTaskCreatedAction.reportActionID]: {pendingAction: null}},
   230	        },
   231	    ];
   232	
   233	    // FOR TASK REPORT
   234	    const failureData: OnyxUpdate[] = [
   235	        {
   236	            onyxMethod: Onyx.METHOD.MERGE,
   237	            key: `${ONYXKEYS.COLLECTION.REPORT}${optimisticTaskReport.reportID}`,
   238	            value: null,
   239	        },
   240	        {
   241	            onyxMethod: Onyx.METHOD.MERGE,
   242	            key: `${ONYXKEYS.COLLECTION.REPORT_ACTIONS}${optimisticTaskReport.reportID}`,
   243	            value: null,
   244	        },
   245	    ];
   246	
   247	    if (assigneeChatReport && assigneeChatReportID) {
   248	        assigneeChatReportOnyxData = ReportUtils.getTaskAssigneeChatOnyxData(
   249	            currentUserAccountID,
   250	            assigneeAccountID,
   251	            taskReportID,
   252	            assigneeChatReportID,
   253	            parentReportID,
   254	            title,
   255	            assigneeChatReport,
   256	        );
   257	
   258	        optimisticData.push(...assigneeChatReportOnyxData.optimisticData);
   259	        successData.push(...assigneeChatReportOnyxData.successData);
   260	        failureData.push(...assigneeChatReportOnyxData.failureData);
   261	    }
   262	
   263	    // Now that we've created the optimistic chat report and chat reportActions, we can update the parent report data
   264	    // FOR PARENT REPORT (SHARE DESTINATION)
   265	    optimisticData.push(
   266	        {
   267	            onyxMethod: Onyx.METHOD.MERGE,
   268	            key: `${ONYXKEYS.COLLECTION.REPORT}${parentReportID}`,
   269	            value: optimisticParentReport,
   270	        },
   271	        {
   272	            onyxMethod: Onyx.METHOD.MERGE,
   273	            key: `${ONYXKEYS.COLLECTION.REPORT_ACTIONS}${parentReportID}`,
   274	            value: {[optimisticAddCommentReport.reportAction.reportActionID]: optimisticAddCommentReport.reportAction as OnyxTypes.ReportAction},
   275	        },
   276	    );
   277	
   278	    const shouldUpdateNotificationPreference = !isEmptyObject(parentReport) && ReportUtils.isHiddenForCurrentUser(parentReport);
   279	    if (shouldUpdateNotificationPreference) {
   280	        optimisticData.push({
   281	            onyxMethod: Onyx.METHOD.MERGE,
   282	            key: `${ONYXKEYS.COLLECTION.REPORT}${parentReportID}`,
   283	            value: {
   284	                participants: {
   285	                    [currentUserAccountID]: {notificationPreference: CONST.REPORT.NOTIFICATION_PREFERENCE.ALWAYS},
   286	                },
   287	            },
   288	        });
   289	    }
   290	
   291	    // FOR QUICK ACTION NVP
   292	    optimisticData.push({
   293	        onyxMethod: Onyx.METHOD.SET,
   294	        key: ONYXKEYS.NVP_QUICK_ACTION_GLOBAL_CREATE,
   295	        value: {
   296	            action: CONST.QUICK_ACTIONS.ASSIGN_TASK,
   297	            chatReportID: parentReportID,
   298	            isFirstQuickAction: isEmptyObject(quickAction),
   299	            targetAccountID: assigneeAccountID,
   300	        },
   301	    });
   302	    failureData.push({
   303	        onyxMethod: Onyx.METHOD.SET,
   304	        key: ONYXKEYS.NVP_QUICK_ACTION_GLOBAL_CREATE,
   305	        value: quickAction ?? null,
   306	    });
   307	
   308	    // If needed, update optimistic data for parent report action of the parent report.
   309	    const optimisticParentReportData = ReportUtils.getOptimisticDataForParentReportAction(parentReportID, currentTime, CONST.RED_BRICK_ROAD_PENDING_ACTION.ADD);
   310	    optimisticParentReportData.forEach((parentReportData) => {
   311	        if (isEmptyObject(parentReportData)) {
   312	            return;
   313	        }
   314	        optimisticData.push(parentReportData);
   315	    });
   316	
   317	    // FOR PARENT REPORT (SHARE DESTINATION)
   318	    successData.push({
   319	        onyxMethod: Onyx.METHOD.MERGE,
   320	        key: `${ONYXKEYS.COLLECTION.REPORT_ACTIONS}${parentReportID}`,
   321	        value: {[optimisticAddCommentReport.reportAction.reportActionID]: {pendingAction: null, isOptimisticAction: null}},
   322	    });
   323	
   324	    // FOR PARENT REPORT (SHARE DESTINATION)
   325	    failureData.push({
   326	        onyxMethod: Onyx.METHOD.MERGE,
   327	        key: `${ONYXKEYS.COLLECTION.REPORT_ACTIONS}${parentReportID}`,
   328	        value: {
   329	            [optimisticAddCommentReport.reportAction.reportActionID]: {
   330	                errors: ErrorUtils.getMicroSecondOnyxErrorWithTranslationKey('task.genericCreateTaskFailureMessage'),
   331	            },
   332	        },
   333	    });
   334	    failureData.push({
   335	        onyxMethod: Onyx.METHOD.MERGE,
   336	        key: `${ONYXKEYS.COLLECTION.REPORT}${parentReportID}`,
   337	        value: {
   338	            hasOutstandingChildTask: parentReport?.hasOutstandingChildTask,
   339	        },
   340	    });
   341	
   342	    const parameters: CreateTaskParams = {
   343	        parentReportActionID: optimisticAddCommentReport.reportAction.reportActionID,
   344	        parentReportID,
   345	        taskReportID: optimisticTaskReport.reportID,
   346	        createdTaskReportActionID: optimisticTaskCreatedAction.reportActionID,
   347	        htmlTitle: optimisticTaskReport.reportName,
   348	        description: optimisticTaskReport.description,
   349	        assignee: assigneeEmail,
   350	        assigneeAccountID,
   351	        assigneeChatReportID,
   352	        assigneeChatReportActionID: assigneeChatReportOnyxData?.optimisticAssigneeAddComment?.reportAction.reportActionID,
   353	        assigneeChatCreatedReportActionID: assigneeChatReportOnyxData?.optimisticChatCreatedReportAction?.reportActionID,
   354	    };
   355	
   356	    playSound(SOUNDS.DONE);
   357	    API.write(WRITE_COMMANDS.CREATE_TASK, parameters, {optimisticData, successData, failureData});
   358	
   359	    if (!isCreatedUsingMarkdown) {
   360	        InteractionManager.runAfterInteractions(() => {
